"""intents — 唯一意图开关（一份 json）+ 动态加载

唯一开关 = `voice_agent/intent_config.json` 的 `intent_registry`（文件最前面）：

    {"intent": "命令列表", "says": [...], "desc": "具体作用", "enabled": true, "tag": "system"}

  · 意图（intent） → 说法（says） → 具体作用（desc） → 是否开启（enabled） → 域（tag）
  · enabled：true=参与 ｜ false=不参与（**任何路径都不执行**）｜ null=跟意图域
             （tag == 当前域 或 tag == system）
  · says 为空的 launch_app/open_url/open_file：说法由 apps/urls/files 的
    「名字 + 别名」×「打开/启动/运行…」**自动展开**（不写进 json，保持干净）
  · 动态加载：每次匹配前看 mtime+size，改完保存立即生效（不用重启）

调用点：
  · hook.get_system_fp(cfg) → 本模块的匹配表
  · reply 的 dispatch 包装 + ACTIONS 门槛 → enabled() 控制
  · 启动 install(cfg) → 打一行口径日志
"""
from __future__ import annotations

import json
import threading
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent      # voice_agent 目录
HERE = Path(__file__).resolve().parent
DEFAULT_FILE = "intent_config.json"
TMP_TABLE = HERE / "table_registry.json"           # fp 建表用的占位路径（不写盘）

_LOCK = threading.RLock()
_CACHE = {"key": None, "fp": None, "reg": None, "domain": None, "summary": None}
_ENT = {"cfg": None}          # 唯一 json 的 Config（闭集来源；打开类动作用）
STATE = HERE / "domain_state.json"     # 运行期领域选择（按 profile 记；重启仍在）
_STATE_CACHE = {"key": None, "val": {}}

# ── 带变量的说法：掩码表只能匹配【固定说法】，「第 5 条」这种走模式匹配 ──────
import re as _re

_NUM = r"[0-9]+|[零一二三四五六七八九十百千两]+"
_FOLD = r"默认收藏夹|默认|课程|哄up收藏夹|哄up|明日方舟"
PATTERNS = [
    ("fav_show", _re.compile(rf"^(?:打开|开|看看)?\s*(?P<folder>{_FOLD})?\s*(?:收藏夹)?\s*"
                             rf"第\s*(?P<n>{_NUM})\s*(?:条|个|集|部)?\s*(?:是|叫)\s*(?:什么|啥)$")),
    ("fav_open", _re.compile(rf"^(?:打开|开|播放|放|看|看看)?\s*(?P<folder>{_FOLD})?\s*(?:收藏夹)?\s*"
                             rf"第\s*(?P<n>{_NUM})\s*(?:条|个|集|部)$")),
    ("fav_open", _re.compile(rf"^(?:打开|开|看看)?\s*(?P<folder>{_FOLD})?\s*收藏夹$")),
    ("fav_sync", _re.compile(rf"^(?:刷新|同步|更新|重新同步)\s*(?P<folder>{_FOLD})?\s*收藏夹$")),
]
_FILLER = ("帮我", "请", "麻烦", "给我", "我要", "我想", "然后", "接着", "现在", "顺便")


def match_pattern(text):
    """带变量的命令（「打开第5条」）→ (intent, arg)；不中返回 None"""
    t = str(text or "").strip().strip("。！？.!?,，、;：\"'“”‘’ ")
    for f in _FILLER:
        if t.startswith(f):
            t = t[len(f):].strip()
    for intent, pat in PATTERNS:
        m = pat.match(t)
        if not m:
            continue
        g = m.groupdict()
        folder = (g.get("folder") or "").strip()
        n = (g.get("n") or "").strip()
        return intent, (f"{folder}|{n}" if n else folder)
    return None

# 领域标签：中文为准（游戏/运维/日常/system），旧的英文值也认
TAG_ALIAS = {"game": "游戏", "aoe4": "游戏", "游戏": "游戏",
             "ops": "运维", "运维": "运维", "devops": "运维",
             "office": "日常", "daily": "日常", "日常": "日常", "desktop": "日常",
             "system": "system", "系统": "system"}
DOMAINS = ("日常", "游戏", "运维")


def norm_tag(t):
    s = str(t).strip()
    return TAG_ALIAS.get(s.lower(), s)


def _state():
    """领域选择（按 profile 路径）；按 mtime 缓存"""
    try:
        st = STATE.stat()
        key = (st.st_mtime_ns, st.st_size)
    except Exception:
        key = None
    if _STATE_CACHE["key"] == key:
        return _STATE_CACHE["val"]
    try:
        val = json.loads(STATE.read_text(encoding="utf-8")) if key else {}
    except Exception:
        val = {}
    _STATE_CACHE.update({"key": key, "val": val})
    return val


def _state_key(cfg):
    return str(getattr(cfg, "path", "") or "?")


def set_domain(cfg, name):
    """切换当前意图域（游戏/运维/日常）→ 落盘 + 立即重建匹配表"""
    nm = norm_tag(name)
    if nm not in DOMAINS:
        return None
    try:
        d = dict(_state())
        d[_state_key(cfg)] = nm
        STATE.write_text(json.dumps(d, ensure_ascii=False, indent=2), encoding="utf-8")
        _STATE_CACHE["key"] = None
    except Exception:
        pass
    load(cfg, force=True)
    return nm


def _log(msg, tag="SYS"):
    try:
        from dlog import log
        log(msg, tag)
    except Exception:
        print(msg, flush=True)


# ── 位置 / 意图域 ──────────────────────────────────────────────
def registry_file(cfg=None):
    name = None
    try:
        name = (cfg.behavior or {}).get("intent_registry_file")
    except Exception:
        pass
    p = Path(str(name or DEFAULT_FILE))
    return p if p.is_absolute() else (ROOT / p)


def domain_of(cfg):
    """当前意图域：① 运行期选择(domain_state.json，按 profile) ② behavior.intent_domain
    ③ **默认「日常」**（用户口径：默认日常，可以直接说「打开网站/网页」；要玩/运维就切换）"""
    try:
        nm = _state().get(_state_key(cfg))
        if nm:
            return norm_tag(nm)
    except Exception:
        pass
    try:
        d = (cfg.behavior or {}).get("intent_domain")
        if d:
            return norm_tag(d)
    except Exception:
        pass
    return "日常"


def _iid(e):
    return e.get("intent") or e.get("id")


# ── 读配置 ────────────────────────────────────────────────────
def _read(p: Path):
    try:
        raw = json.loads(p.read_text(encoding="utf-8"))
    except Exception as e:
        _log(f"   ⚠️ 意图清单读取失败（{p}）: {type(e).__name__}: {e}", "WARN")
        return {"tags": {}, "intents": [], "destructive": []}, {}
    reg = raw.get("intent_registry") or {}
    intents = list(reg.get("intents") or [])
    return ({"tags": dict(reg.get("tags") or {}),
             "intents": intents,
             "destructive": list(reg.get("destructive") or [])}, raw)


def resolve_enabled(e, domain):
    """开没开：enabled（true/false，省略/null 视为 true）**且** 域匹配

    为什么这样定：enabled 是"这条意图自己开没开"，域由 tag 决定 ——
    所以 aoe4 域里 office 的意图不会因为 enabled=true 就误触发，
    而 dictation_on/off、清空输入、命令列表这些 system 标签的在任何域都生效。
    """
    v = e.get("enabled", True)
    if v is None:
        v = True
    if not v:
        return False
    tag = norm_tag(e.get("tag") or "system")
    return tag == "system" or tag == domain


# ── 建匹配表 ──────────────────────────────────────────────────
def _check_pinyin(reg):
    """校验 json 里写的 pinyin 和实际算出来的标注一致（不一致就喊出来）

    为什么要有：json 里写明白拼音是用户要求；一旦折叠规则变了，写下来的拼音
    就会和实际匹配用的不一致 —— 这类漂移必须能被发现。
    """
    try:
        from .pinyin import annotate
    except Exception:
        return 0
    bad = 0
    for e in reg.get("intents") or []:
        says = e.get("says") or []
        py = e.get("pinyin") or []
        if not says or len(py) != len(says):
            continue
        for s, p in zip(says, py):
            try:
                real = annotate(s)
            except Exception:
                continue
            if str(p).strip() and str(p).strip() != str(real).strip():
                bad += 1
                if bad <= 5:
                    _log("   ⚠️ 拼音标注不一致：「%s」写=%s 实际=%s（%s）"
                         % (s, p, real, _iid(e)), "WARN")
    if bad:
        _log("   ⚠️ 拼音标注不一致共 %d 条（改 intent_config.json 里的 pinyin 即可）" % bad,
             "WARN")
    return bad


def _build_fp(reg, domain, min_prefix=3, raw=None):
    from .fastpath import FastPath, DESTRUCTIVE_INTENTS, _norm
    from .pinyin import Encoder

    fp = FastPath(table_path=TMP_TABLE, mode="live")
    fp.entries = []
    fp.enc = Encoder()
    fp.min_prefix = int(min_prefix or 3)
    fp._persist = lambda: None        # 不写盘（内存表；避免每次 install 都落盘）

    for iid in (reg.get("destructive") or []):
        DESTRUCTIVE_INTENTS.add(iid)

    # apps/urls/files → 打开/启动/… + 名字/别名（自动展开）
    expanded = {}
    try:
        from .build_table_domain import entries_from_config
        for intent, arg, trig in entries_from_config(raw or {}):
            if intent in ("launch_app", "open_url", "open_file") and trig:
                expanded.setdefault(intent, []).append((arg, trig))
    except Exception:
        pass

    def _add(intent, arg, triggers, additive=True):
        ts = [_norm(t) for t in triggers if _norm(t)]
        if not ts:
            return
        # ★★ 血债（2026-10-19 用户实测）：dictation_on/off、清空输入、关闭X 原来被
        #   fastpath 标成 destructive → blocked → **A 路整句也拒绝执行** → 掉回主路径 →
        #   parse() 又不认这些意图 → unknown → 直接被当听写打进输入框
        #   （用户：「关闭输入后还他妈路由到听写」）。
        #   现在：registry 里的意图【不受 blocked 影响】—— 执不执行由 enabled 决定
        #   （enabled=true 就是用户明确同意），destructive 只作为"有副作用"的标注。
        DESTRUCTIVE_INTENTS.discard(intent)
        for t in ts:
            fp.enc.mask(t, assign=True)
        fp.entries.append({"intent": intent, "arg": arg, "triggers": ts,
                           "additive": bool(additive),
                           "destructive": intent in DESTRUCTIVE_INTENTS,
                           "markers": {"source": "registry"}})

    on = off = 0
    by_tag = {}
    for e in reg["intents"]:
        iid = _iid(e)
        if not iid:
            continue
        tag = str(e.get("tag") or "system")
        good = resolve_enabled(e, domain)
        by_tag.setdefault(tag, [0, 0])[0 if good else 1] += 1
        if not good:
            off += 1
            continue
        on += 1
        rows = expanded.get(iid)
        if rows:
            for arg, trig in rows:
                _add(iid, arg, trig)
            continue
        says = [s for s in (e.get("says") or []) if isinstance(s, str) and s.strip()]
        if says:
            _add(iid, e.get("arg"), says)
    fp._rebuild()

    parts = ", ".join(f"{t} {v[0]}开/{v[1]}禁" for t, v in sorted(by_tag.items()))
    summary = (f"意图清单：域={domain} ｜ 启用 {on} / 禁用 {off}"
               + (f" ｜ {parts}" if parts else ""))
    return fp, summary


def load(cfg=None, force=False):
    """→ (reg, fp, domain)；按 mtime+size 热加载"""
    p = registry_file(cfg)
    domain = domain_of(cfg)
    try:
        minp = int((cfg.behavior or {}).get("fastpath_min_prefix") or 3)
    except Exception:
        minp = 3
    try:
        st = p.stat()
        key = (str(p), st.st_mtime_ns, st.st_size, domain, minp)
    except Exception:
        key = (str(p), None, None, domain, minp)
    with _LOCK:
        if not force and _CACHE["key"] == key and _CACHE["fp"] is not None:
            return _CACHE["reg"], _CACHE["fp"], _CACHE["domain"]
        old_key = _CACHE["key"]
        reg, raw = _read(p)
        _check_pinyin(reg)
        fp, summary = _build_fp(reg, domain, minp, raw)
        _CACHE.update({"key": key, "fp": fp, "reg": reg, "domain": domain,
                       "summary": summary})
    if old_key is not None and old_key != key:
        _log(f"   ⚡ {summary}（文件已改 → 热加载）")
    return reg, fp, domain


def get_fp(cfg=None):
    """给 hook/runtime 用的匹配表（None 表示没有可匹配的条目）"""
    try:
        reg, fp, _ = load(cfg)
        return fp if (fp is not None and fp.entries) else None
    except Exception:
        return None


def summary(cfg=None):
    """一行口径：意图清单：域=… ｜ 启用 N / 禁用 M ｜ 标签 …"""
    try:
        load(cfg)
        return _CACHE.get("summary") or ""
    except Exception:
        return ""


# ── 开关门槛（任何路径都过这道关）────────────────────────────
def entry(cfg, intent_id, _reg=None):
    reg = _reg
    if reg is None:
        try:
            reg, _, _ = load(cfg)
        except Exception:
            return None
    for e in (reg or {}).get("intents", []):
        if _iid(e) == intent_id:
            return e
    return None


def enabled(cfg, intent_id):
    """意图开没开：不在清单里 → 不拦（保持既有行为）；false → 挡"""
    try:
        e = entry(cfg, intent_id)
        if e is None:
            return True
        return resolve_enabled(e, domain_of(cfg))
    except Exception:
        return True


def tag_of(cfg, intent_id):
    e = entry(cfg, intent_id)
    return (e or {}).get("tag")


def install(cfg):
    """启动时调用：加载 + 打一行口径日志（INFO 可见）+ 给 ACTIONS 装开关门槛"""
    try:
        s = summary(cfg)
        if s:
            _log(s)
        _load_entity_cfg(cfg)      # 唯一 json 的闭集（打开类动作用）
        _install_gate()
        return True
    except Exception as ex:
        _log(f"   ⚠️ 意图清单加载失败: {type(ex).__name__}: {ex}", "WARN")
        return False


def _install_gate():
    """给 actions.ACTIONS 里每个动作套一层【开关门槛】

    为什么放这里而不是只放 dispatch 包装：有些模块 `from actions import dispatch`
    在导入期就拿到了原函数（包装不到）—— 套在 ACTIONS 上则任何调用路径都过这道关。
    顺带给"打开类"意图套上【闭集来源】：本 profile 的 apps/urls/files 是空的时候
    （例如 aoe4 域），用唯一 json（intent_config.json）里的闭集 —— 否则会出现
    「拼音命中了 打开知乎，动作却说 网址闭集里没有知乎」（2026-10-19 用户实测）。
    """
    try:
        import actions as _act
    except Exception:
        return False
    ENTITY = ("launch_app", "open_url", "open_file", "close_app", "site_search",
              "file_search", "exact_search")
    try:
        from . import launch_watch as _lw
    except Exception:
        _lw = None
    n = 0
    for key, fn in list(_act.ACTIONS.items()):
        if getattr(fn, "__oc_gated__", False):
            continue
        f2 = _make_gated(key, fn)
        if key in ENTITY:
            f2 = _wrap_entity(key, f2)
        # ★ 启动类：先满足前提（Steam/Battle.net 先起）+ 拉起后验证本体进程
        if key == "launch_app" and _lw is not None:
            f2 = _lw.wrap_launch(f2)
        _act.ACTIONS[key] = f2
        n += 1
    return n > 0


def _entities_cfg(cfg):
    """本 profile 闭集为空 → 返回一个"用 registry 文件的闭集 + 本 profile 的行为"的代理"""
    try:
        if getattr(cfg, "apps", None) or getattr(cfg, "urls", None) or getattr(cfg, "files", None):
            return cfg
        reg = _ENT["cfg"]
        if reg is None:
            return cfg
        if not (getattr(reg, "apps", None) or getattr(reg, "urls", None)
                or getattr(reg, "files", None)):
            return cfg
        return _CfgProxy(cfg, reg)
    except Exception:
        return cfg


class _CfgProxy:
    """动作需要的"闭集/搜索"来自 other（唯一 json），其余（behavior/path）来自 base"""

    def __init__(self, base, other):
        for k in ("apps", "urls", "files", "app_by_alias", "url_by_alias",
                  "file_by_alias", "search", "triggers", "raw", "intents"):
            try:
                setattr(self, k, getattr(other, k))
            except Exception:
                pass
        self._base = base

    def __getattr__(self, k):
        return getattr(self._base, k)

    def candidates(self):
        try:
            return self._base.candidates()
        except Exception:
            return []


def _wrap_entity(intent_id, fn):
    def with_entities(arg, cfg, dry=False):
        return fn(arg, _entities_cfg(cfg), dry)
    with_entities.__name__ = getattr(fn, "__name__", intent_id)
    with_entities.__oc_entity__ = True
    return with_entities


def _load_entity_cfg(cfg):
    """把唯一 json 读成 Config（给"闭集来源"用）；失败返回 None"""
    try:
        from actions import Config
        p = registry_file(cfg)
        c = Config(str(p))
        _ENT["cfg"] = c
        return c
    except Exception:
        return None


def _make_gated(intent_id, fn):
    def gated(arg, cfg, dry=False):
        try:
            if not enabled(cfg, intent_id):
                return (False,
                        f"意图 {intent_id} 已关闭（intent_config.json → intent_registry "
                        f"里 enabled=false，域 {tag_of(cfg, intent_id)}；"
                        f"改成 true 即生效，无需重启）", None)
        except Exception:
            pass
        return fn(arg, cfg, dry)
    gated.__name__ = getattr(fn, "__name__", intent_id)
    gated.__oc_gated__ = True
    gated.__oc_origin__ = fn
    return gated


